namespace OpenTPW;

/// <summary>Every unproven sound rule (docs/AUDIO.md "Approximation register"); logged once when the sound service starts.</summary>
public static class AudioApproximations
{
	public static readonly (string Id, string Rule)[] All =
	{
		("AUDIO-018", "a positioned mono voice follows the software channel stage of QMixer.dll, which tp.exe selects for every voice (the request flag 1 is ORed in unconditionally at 0x6bc61b, so 0x6d23ab hands QSWaveMixConfigureChannel the mode 0x1000000, whose buffers have no DirectSound 3D object): the source's offset is rotated into the listener's basis (front and up from the camera matrix rows 0x7909b0 and 0x7909a0, right = up x front, 0x1800ce70, 0x1800cf10; the adapters' swap of y and z, 0x6d2640, 0x6d2a10, 0x6d2b20, and QMixer's negation of the third component, 0x18001020, make a rotation, so the camera axes need no mapping), the azimuth atan2(x, z) in degrees (0x1800cb10) becomes a DirectSound pan of 44.444 hundredths of a dB per degree mirrored behind the listener (0x18005730), the gain a volume of 2000 log10(gain) hundredths of a dB (0x1800ca40), and 0x18005830 sets both for a mono wave only (0x18005982 tests the format table 0x1803c6b4); the opposite channel is 10^(-|pan|/2000) of the level; a voice with the any-distance flag (event flag 0x200, speech, music, most interface sounds) is placed flat by the library (0x6bc51d: QSWaveMixSetPosition with the integers 0, 1, 0, 0x18007abd) and is centred at the voice's own gain. Doppler is read: every voice without the loop flag (voice flag 4 makes the request flag 0x40 through 0x6bc628 -> 0x6c5110, which 0x6d22d0 turns into the channel's no-Doppler bit 0x10, tested at 0x1800a1df) takes the factor 1 / (1 + x), x = (direction . relative velocity) / 331.36 (the engine's speed-of-sound scales +0x88 and +0x90 are 1.0 from the table 0x180311f0; tp.exe imports QSWaveMixSetSpeedOfSound but its adapter 0x6d2ce0 is never called), at most 10 (0x1800a178-0x1800a2c3), which 0x18005550 multiplies into the stream frequency (an integer, 0x180055c8-0x180055dd) once the wave has its stream reader (0x18005599-0x180055bd, 0x1800bd40; the library's worker creates it through 0x18024620 for the memory waves tp.exe opens with OpenWaveEx flag 0x11, 0x180033ad); the listener velocity is the current minus the previous place (0x6b79d0 -> 0x6d2a10 -> 0x6d27b0, sent because bit 0x40 of the record's flags is clear, which nothing sets: 0x6b9c50 clears the flags and 0x6b9930 sets only 0x800), per changed listener update and without a time base, so it depends on the frame rate; the previous place is the library's own (+8 of the sound system object, zero when the process starts), the update compares place, front and up byte for byte first (0x6b8b60), so a camera that stands still keeps the last velocity, and in a park whose camera does not move after its first frame that is the whole place minus the lobby's (0, 0, -50), which the front end sends every frame (0x54e6f3-0x54e70e); a flat voice sits straight ahead of the listener (AudioListener.DopplerFactor, AudioDopplerTests); OpenTPW sends the lobby listener only from the front-end flow of GameFlow, other scenes without a park (the TPI viewer) do not. Open: the Doppler factor is not applied (AudioListener.DopplerEnabled is off): the gameplay capture of the PC game (v2.0, Dutch) shows no pitch change where this reading predicts one: the advisor's lobby sentence 'Typ eerst je naam in het tekstvenster.' (0:10 and 28:43) and help sentences repeated at 1:37, 30:18 and 80:45 play at the same speed (best resampling scale 1.00 within 0.01, spectrogram correlation 0.78 to 0.90), although the reading gives the first lobby the velocity (0, 0, -50) (a factor of 0.87 for a flat voice), the lobby after a park that velocity minus the park's last place (about 0.6 for a Jungle camera) and a park, until its camera moves, its first place minus the lobby's (about 1.2 at the Jungle start); the reading therefore misses a gate or a reset that keeps the factor at 1 (not found in the channel flags 0x6d22d0, the readiness gate 0x18005599, the speed-of-sound scale 0x18009920, the velocity message 0x180098c0), or the sound system is rebuilt per lobby and park, which would reset the previous place too (hypothesis, not read); round 10 ruled out further candidates by reading: a channel's default flag word is 0x101 (the default parameter block 0x180310f0, +0x5c = 0x1803114c), so the no-Doppler bit 0x10 is clear unless tp.exe sets it; the start of a sample builds the word from the node's flag word +0x14 (0x6d2380 -> 0x6d2320 -> 0x6d22d0) and only a loop's 0x40 (0x6c5110) reaches 0x10; every voice recompute ends by jumping through vtable +0x18 of the voice's attached output (0x18007f99), which is the channel's update 0x18005830 (ending in 0x18005550) if that output is the software channel (inferred, not read to the creation), and 0x18009d90 marks every voice dirty on a listener move, 0x18008330 and the pump 0x18007640 recompute them; the listener velocity of every changed update is that update's place minus the previous update's place (0x6b79d0 hands the previous place to 0x6d2a10 every time, and the initial one is zero: 0x6b73b7-0x6b73bd), so an update that only turns the camera zeroes it and a stale velocity lasts only until the next changed update (the lobby's own call repeats one value, so it makes a single update); QMixer's time-based tracker (option bit 8, 0x18009cf4) is not enabled by the listener record (flags 0 or 0x800, 0x6b9930); an unresolved lead: the request word +0xc has 0xc0 ORed in for every voice without voice flag 0x20000 (0x6bc2af, 0x40 maps to the no-Doppler bit through 0x6d22d0) and 2 ORed in when the sound system's flags 8 and 0x100 (reverb) are both set (0x6b9acb), which is the test of a second EnableChannel from the request word (0x6c5690, +0xc & 0x1a): whether that second send runs for a started voice, and after or before the start's own (0x6d2380), is not read, so with the original's reverb on every such voice may be exempt from Doppler; also open: the pause's listener height of 10000 (UI-096's sound side), the volume's quantisation to hundredths of a decibel is applied to the distance gain only, not to the product with the voice's own volume (at most 0.005 dB), and the stream frequency's rounding to the device's units (0x1800c760); a coaster save also stores the handle numbers of the train loops (train +0x64 and +0x68, 0x43780A..0x437821, restored raw at 0x438400), which only mean something to the previous session's sound library: OpenTPW starts no loop for a loaded train until its next setup"),
		("AUDIO-038", "the voice pool of 12 (tp.exe 0x6b62b0) ranks the held chains (screams) with the running sentences, placed sounds and one-shots of the event system by priority and ground distance (0x6bb9f0; a started any-distance voice sits at the origin of the sound space, where its sample start put it, 0x6bc51d), a voice entering only while its rank exceeds the pool's lowest (0x6b6bc0) and among equal ranks the newer voice keeping its slot (0x6b6a80 links a new voice at the head of the voice list); a voice out of range without the any-distance flag (event flag 0x200, voice flag 8 at 0x6bca44) has its sample stopped by mixer message 3 (0x6bca70 -> 0x6b8d60 -> 0x6bb7c0) and its handle at +0x24 cleared, is not ticked, and returns by the sample setup 0x6bc410: one-shots, loops and sentence segments restart from their beginning with a fresh volume, pitch and delay draw, a chain starts no new child but its children already playing play out. Open: a sentence stopped inside the decoder's last look-ahead (the 0x2400-byte read of 0x6bb510 reaching the end of the segment's data runs the refill 0x6bde00, which advances the selected descriptor) resumes on its successor, which this replay of the whole segment does not do; the sentence successor is chosen when a segment starts, not when the decoder's data runs out (EXT:sentence-prefetch); the initial submission's admission, the group-enable stop and restart of a voice (0x6bc760, the enable bytes +0x44..+0x47 of the sound system) and voices the mixer plays outside the event system, including the children a chain makes, which do not compete"),
		("AUDIO-040", "FADEOBJ uses configured quality > threshold, service-owned integer-decay tails, shared 100/250 ms polls, subtype-specific stop/continuation and terminal cleanup; the poll's effective volume is the worker thread's 53-bit x87 arithmetic (0x6bb860 on the thread of 0x6b9e30, control word 0x27F) and every main-thread computation the 24-bit one (0x7F). AUDIO-040 retains the host monotonic startup phase and the serialized poll/admission order of the original's Sleep(100/250) worker, which depends on the operating system's scheduler, and a missing host SoundQuality taking the loaded SAM DEFAULTQUALITY (supplied 50; FADETOGGLE 30) instead of the original user's saved preference; these are explicit compatibility policies, not observed original timing. AUDIO-038 admission/restart and existing general sentence approximations remain separate."),
	};

	private static bool logged;

	public static void LogOnce()
	{
		if ( logged )
			return;
		logged = true;
		foreach ( var (id, rule) in All )
			Log.Trace( $"[APPROX:{id}] {rule}" );
	}
}
